Func<Orc.Cards.CardEventView, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{
    if (view.Host is not Orc.Game.Cards.UnitCard host) { return; }
    if (view.Player is not Orc.Game.Players.Player current || !object.ReferenceEquals(host.Owner, current)) { return; }
    if (!host.TryGetData<Orc.Game.Cards.ActionRecordData>(out var record)) { return; }
    if (record.TurnMoves != 0 || record.TurnAttacks != 0) { return; }
    if (host.GetData<Orc.Game.Cards.UnitStateData>().IsDestroyed) { return; }

    await host.RepairDefenseAsync(ct); // 抢修：回满
};

Func<Orc.Cards.CardEventView, Context, CancellationToken, Task> HandleMovedAsync = async (view, ctx, ct) =>
{
    if (view.Host is not Orc.Game.Cards.UnitCard host) { return; }
    if (view.Unit is not Orc.Game.Cards.UnitCard unit || !object.ReferenceEquals(unit, host)) { return; }

    var position = unit.GetData<Orc.Game.Cards.UnitStateData>().Position;
    if (position is not null && position.Name.StartsWith("前线", StringComparison.Ordinal))
    {
        await unit.Keywords.RevokeAsync("抢修"); // 位于前线即失去
    }
};

Func<Orc.Cards.CardEventView, Context, CancellationToken, Task> HandleDeployedAsync = async (view, ctx, ct) =>
{
    if (view.Host is not Orc.Game.Cards.UnitCard host) { return; }
    if (view.Unit is not Orc.Game.Cards.UnitCard unit || !object.ReferenceEquals(unit, host)) { return; }

    var position = unit.GetData<Orc.Game.Cards.UnitStateData>().Position;
    if (position is not null && position.Name.StartsWith("前线", StringComparison.Ordinal))
    {
        await unit.Keywords.RevokeAsync("抢修"); // 部署在前线即失去
    }
};
